-- State transitions declared for DigestSubscription: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION digest.digest_subscriptions_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('subscribed', 'unsubscribed'), ('unsubscribed', 'subscribed'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: digest_subscriptions.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_digest_subscriptions__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS digest_subscriptions_state_transition_check ON digest.digest_subscriptions;
CREATE TRIGGER digest_subscriptions_state_transition_check
    BEFORE UPDATE OF "state" ON digest.digest_subscriptions
    FOR EACH ROW EXECUTE FUNCTION digest.digest_subscriptions_state_transition_check();
